import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type ComponentNameProps = Record<string, any>;

const SweepLayer: React.FC<{
  color: string;
  rxIn: [number, number];
  lxOut: [number, number];
  p: number;
  depth: number;
  width: number;
  height: number;
  startX: number;
  endX: number;
}> = ({ color, rxIn, lxOut, p, depth, width, height, startX, endX }) => {
  const wipeEase = Easing.bezier(0.65, 0, 0.35, 1);

  const rx = interpolate(p, rxIn, [startX, endX], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: wipeEase,
  });

  const lx = interpolate(p, lxOut, [startX, endX], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: wipeEase,
  });

  const d = `
    M ${lx} 0
    L ${rx} 0
    L ${rx + depth} ${height / 2}
    L ${rx} ${height}
    L ${lx} ${height}
    L ${lx + depth} ${height / 2}
    Z
  `;

  // Fully invisible before entrance and after exit
  const display = p < rxIn[0] || p > lxOut[1] ? "none" : undefined;

  return (
    <path
      d={d}
      fill={color}
      style={{
        transition: "none",
        display,
      }}
    />
  );
};

const FlyChevron: React.FC<{
  p: number;
  delay: number;
  duration: number;
  color: string;
  thickness: number;
  width: number;
  height: number;
  depth: number;
  startX: number;
  endX: number;
}> = ({ p, delay, duration, color, thickness, height, depth, startX, endX }) => {
  const lineP = interpolate(p, [delay, delay + duration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.65, 0, 0.35, 1),
  });

  const x = interpolate(lineP, [0, 1], [startX, endX]);
  const opacity = interpolate(lineP, [0, 0.1, 0.9, 1], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const d = `
    M ${x} 0
    L ${x + depth} ${height / 2}
    L ${x} ${height}
  `;

  const display = p < delay || p > delay + duration ? "none" : undefined;

  return (
    <path
      d={d}
      stroke={color}
      strokeWidth={thickness}
      fill="none"
      strokeLinecap="square"
      opacity={opacity}
      style={{
        transition: "none",
        display,
      }}
    />
  );
};

const SpeedLine: React.FC<{
  y: number;
  length: number;
  thickness: number;
  delay: number;
  duration: number;
  color: string;
  p: number;
  startX: number;
  endX: number;
}> = ({ y, length, thickness, delay, duration, color, p, startX, endX }) => {
  const lineP = interpolate(p, [delay, delay + duration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const x = interpolate(lineP, [0, 1], [startX - length, endX]);
  const opacity = interpolate(lineP, [0, 0.1, 0.9, 1], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const display = p < delay || p > delay + duration ? "none" : undefined;

  return (
    <line
      x1={x}
      y1={y}
      x2={x + length}
      y2={y}
      stroke={color}
      strokeWidth={thickness}
      opacity={opacity}
      strokeLinecap="round"
      style={{
        transition: "none",
        display,
      }}
    />
  );
};

const generateLines = (
  count: number,
  delayOffset: number,
  delayRange: number,
  w: number,
  h: number,
  c1: string,
  c2: string,
  c3: string
) => {
  return new Array(count).fill(0).map((_, i) => {
    const y = random(`y-${delayOffset}-${i}`) * h;
    const length = w * 0.1 + random(`len-${delayOffset}-${i}`) * w * 0.4;
    const thickness = (w / 1920) * (2 + random(`th-${delayOffset}-${i}`) * 6);
    const delay = delayOffset + random(`del-${delayOffset}-${i}`) * delayRange;
    const duration = 0.2 + random(`dur-${delayOffset}-${i}`) * 0.15;

    const colorType = random(`col-${delayOffset}-${i}`);
    let color = c3;
    if (colorType > 0.6) color = c1;
    else if (colorType > 0.3) color = c2;

    return { y, length, thickness, delay, duration, color };
  });
};

const ComponentName: React.FC<ComponentNameProps> = ({
  primaryColor = "#E31B33",
  secondaryColor = "#7A101C",
  accentColor = "#80858F",
  backgroundColor = "#0B0C10",
  transparentBackground = true,
  durationInSeconds = 4,
  titleText = "Full Video on YouTube",
  subtitleText = "Watch Now",
  titleColor = "#FFFFFF",
  subtitleColor = "#E31B33",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const p = frame / totalFrames;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive layout math
  const depth = height * 0.4;
  const startX = -depth - width * 0.2;
  const endX = width * 1.2;
  const scale = width / 1920;
  const canvasScale = Math.min(width, height) / 1080;

  // Generate deterministic speed lines
  const linesIn = useMemo(
    () => generateLines(20, 0.0, 0.25, width, height, primaryColor, secondaryColor, accentColor),
    [width, height, primaryColor, secondaryColor, accentColor]
  );
  const linesHold = useMemo(
    () => generateLines(15, 0.3, 0.2, width, height, primaryColor, secondaryColor, accentColor),
    [width, height, primaryColor, secondaryColor, accentColor]
  );
  const linesOut = useMemo(
    () => generateLines(20, 0.6, 0.25, width, height, primaryColor, secondaryColor, accentColor),
    [width, height, primaryColor, secondaryColor, accentColor]
  );

  // Staggered text animations starting as the transition fills the screen (p = 0.35 to 0.6)
  const badgeP = interpolate(p, [0.35, 0.55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const badgeOpacity = interpolate(p, [0.35, 0.45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const badgeY = interpolate(badgeP, [0, 1], [40, 0]);

  const titleP = interpolate(p, [0.4, 0.6], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const titleOpacity = interpolate(p, [0.4, 0.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(titleP, [0, 1], [50, 0]);

  const subP = interpolate(p, [0.45, 0.65], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const subOpacity = interpolate(p, [0.45, 0.55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const subY = interpolate(subP, [0, 1], [40, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        {/* Layer 1: Background Speed Lines (Visible during sweeps) */}
        {linesIn.map((line, i) => (
          <SpeedLine key={`in-${i}`} {...line} p={p} startX={startX} endX={endX} />
        ))}
        {linesOut.map((line, i) => (
          <SpeedLine key={`out-${i}`} {...line} p={p} startX={startX} endX={endX} />
        ))}

        {/* Layer 2: The Wipes */}
        <SweepLayer
          color={secondaryColor}
          rxIn={[0.0, 0.3]}
          lxOut={[2.0, 3.0]} // Delayed infinitely so it holds
          p={p}
          depth={depth}
          width={width}
          height={height}
          startX={startX}
          endX={endX}
        />
        <SweepLayer
          color={primaryColor}
          rxIn={[0.05, 0.35]}
          lxOut={[2.0, 3.0]} // Delayed infinitely so it holds
          p={p}
          depth={depth}
          width={width}
          height={height}
          startX={startX}
          endX={endX}
        />
        <SweepLayer
          color={backgroundColor}
          rxIn={[0.1, 0.4]}
          lxOut={[2.0, 3.0]} // Delayed infinitely so it holds the dark background till the end
          p={p}
          depth={depth}
          width={width}
          height={height}
          startX={startX}
          endX={endX}
        />

        {/* Layer 3: Foreground Elements (Visible over the dark hold phase) */}
        {linesHold.map((line, i) => (
          <SpeedLine key={`hold-${i}`} {...line} p={p} startX={startX} endX={endX} />
        ))}

        <FlyChevron
          p={p}
          delay={0.0}
          duration={0.35}
          color={accentColor}
          thickness={4 * scale}
          width={width}
          height={height}
          depth={depth}
          startX={startX}
          endX={endX}
        />
        <FlyChevron
          p={p}
          delay={0.08}
          duration={0.35}
          color={primaryColor}
          thickness={8 * scale}
          width={width}
          height={height}
          depth={depth}
          startX={startX}
          endX={endX}
        />
        <FlyChevron
          p={p}
          delay={0.65}
          duration={0.35}
          color={accentColor}
          thickness={4 * scale}
          width={width}
          height={height}
          depth={depth}
          startX={startX}
          endX={endX}
        />
        <FlyChevron
          p={p}
          delay={0.75}
          duration={0.35}
          color={primaryColor}
          thickness={8 * scale}
          width={width}
          height={height}
          depth={depth}
          startX={startX}
          endX={endX}
        />
      </svg>

      {/* Layer 4: Interactive/Call to Action Text Overlays */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          padding: `0 ${60 * canvasScale}px`,
          textAlign: "center",
          fontFamily: spaceGroteskFamily,
          pointerEvents: "none",
        }}
      >
        {/* YouTube Pill Badge */}
        <div
          style={{
            opacity: badgeOpacity,
            transform: `translateY(${badgeY}px) scale(${badgeP})`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            backgroundColor: "rgba(255, 255, 255, 0.07)",
            border: `1.5px solid rgba(255, 255, 255, 0.15)`,
            borderRadius: 9999,
            padding: `${14 * canvasScale}px ${26 * canvasScale}px`,
            marginBottom: 36 * canvasScale,
            gap: 12 * canvasScale,
            boxShadow: "0 10px 40px rgba(0, 0, 0, 0.4)",
            transition: "none",
          }}
        >
          <svg
            viewBox="0 0 24 24"
            style={{
              width: 32 * canvasScale,
              height: 32 * canvasScale,
              fill: "#FF0000",
            }}
          >
            <path d="M23.498 6.163a3.003 3.003 0 0 0-2.11-2.11C19.517 3.545 12 3.545 12 3.545s-7.517 0-9.388.507a3.003 3.003 0 0 0-2.11 2.11C0 8.033 0 12 0 12s0 3.967.502 5.837a3.003 3.003 0 0 0 2.11 2.11c1.871.507 9.388.507 9.388.507s7.517 0 9.388-.507a3.003 3.003 0 0 0 2.11-2.11C24 15.967 24 12 24 12s0-3.967-.502-5.837zM9.545 15.568V8.432L15.818 12l-6.273 3.568z" />
          </svg>
          <span
            style={{
              color: "#FFFFFF",
              fontSize: 22 * canvasScale,
              fontWeight: 800,
              letterSpacing: "0.06em",
              textTransform: "uppercase",
            }}
          >
            YouTube
          </span>
        </div>

        {/* Main Header Call to Action */}
        <h1
          style={{
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            color: titleColor,
            fontSize: 78 * canvasScale,
            fontWeight: 800,
            lineHeight: 1.15,
            margin: 0,
            marginBottom: 28 * canvasScale,
            letterSpacing: "-0.02em",
            maxWidth: 820 * canvasScale,
            textShadow: "0 4px 20px rgba(0,0,0,0.5)",
            transition: "none",
          }}
        >
          {titleText}
        </h1>

        {/* Subtitle Accent Label */}
        <div
          style={{
            opacity: subOpacity,
            transform: `translateY(${subY}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              backgroundColor: subtitleColor,
              color: "#FFFFFF",
              padding: `${12 * canvasScale}px ${28 * canvasScale}px`,
              borderRadius: 8 * canvasScale,
              fontSize: 22 * canvasScale,
              fontWeight: 800,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
              boxShadow: `0 8px 30px ${subtitleColor}50`,
            }}
          >
            {subtitleText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;